import { useState } from 'react';
import { Link } from 'react-router-dom';
import styles from '../styles/AboutPage.module.css';

import meImg from '../assets/me.jpg';
import elem1 from '../assets/elem1.jpg';
import elem2 from '../assets/elem2.jpg';
import spa1 from '../assets/spa1.jpg';
import spa2 from '../assets/spa2.jpg';
import spa3 from '../assets/spa3.jpg';
import spa4 from '../assets/spa4.jpg';
import spa5 from '../assets/spa5.jpg';
import inspo from '../assets/inspo.jpg';
import sl1 from '../assets/sl1.jpg';
import sl2 from '../assets/sl2.jpg';
import sl3 from '../assets/sl3.jpg';
import sl4 from '../assets/sl4.jpg';
import sl5 from '../assets/sl5.jpg';

function AboutPage() {
  const [darkMode, setDarkMode] = useState(false);
  const toggleTheme = () => setDarkMode(prev => !prev);

  return (
    <div className={darkMode ? styles['dark-mode'] : ''}>
      {/* Header */}
      <header className={styles.header}>
        <h1>My Personal Interests</h1>
        <nav>
          <ul className={styles.navList}>
            <li><Link to="/">Home</Link></li>
            <li><Link to="/about" className={styles.active}>About</Link></li>
            <li><Link to="/contact">Contact</Link></li>
            <li><Link to="/register">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className={styles.themeToggle} onClick={toggleTheme}>
        Toggle Dark/Light
      </button>

      {/* My Story */}
      <section className={styles.aboutSection}>
        <h2>My Story Through Dance</h2>
        <img src={meImg} alt="Photo of Donato" />
        <p>
          My name is <strong>Donato G. Ureta Jr.</strong>, also known as <strong>DJ</strong>.
          I am from San Eugenio, Aringay, La Union. This webpage shares my personal
          journey in discovering my passion for dance and how it became an important part of my life.
        </p>
      </section>

      {/* Elementary School Dance */}
      <section className={styles.aboutSection}>
        <h2>My First Dance Experience in Elementary School</h2>
        <div className={styles.imageRow}>
          <img src={elem1} alt="Festival dance performance 1" />
          <img src={elem2} alt="Festival dance performance 2" />
        </div>
        <p>At first, I was not really interested in dancing, but I soon discovered my love for movement and rhythm.</p>
      </section>

      {/* Special Dance Moments */}
      <section className={styles.aboutSection}>
        <h2>Special Dance Moments</h2>
        <div className={styles.imageRow}>
          <img src={spa1} alt="Special dance 1" />
          <img src={spa2} alt="Special dance 2" />
          <img src={spa3} alt="Special dance 3" />
          <img src={spa4} alt="Special dance 4" />
          <img src={spa5} alt="Special dance 5" />
        </div>
      </section>

      {/* School Life Dance */}
      <section className={styles.aboutSection}>
        <h2>School Life Dance</h2>
        <div className={styles.imageRow}>
          <img src={sl1} alt="School dance 1" />
          <img src={sl2} alt="School dance 2" />
          <img src={sl3} alt="School dance 3" />
          <img src={sl4} alt="School dance 4" />
          <img src={sl5} alt="School dance 5" />
        </div>
      </section>

      {/* Inspirations */}
      <section className={styles.aboutSection}>
        <h2>Dance Inspirations</h2>
        <div className={styles.imageRow}>
          <img src={inspo} alt="Dance inspiration" />
        </div>
      </section>

      {/* Fun Facts */}
      <section className={styles.aboutSection}>
        <h2>Fun Dance Facts</h2>
        <ul>
          <li>The waltz originated in Austria in the late 18th century.</li>
          <li>Ballet dancers can perform on pointe after years of training.</li>
          <li>Hip Hop dance culture began in the 1970s in New York City.</li>
          <li>Salsa is a popular Latin dance with roots in Cuba and Puerto Rico.</li>
          <li>Flamenco involves intricate footwork and expressive hand movements.</li>
        </ul>
      </section>

      <blockquote>“Dance is not just movement, it is the story of my journey.”</blockquote>

      <footer className={styles.footer}>
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Dance Journey. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default AboutPage;
